const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-llm-model-warmup", node: "Code: Log Result" } });
const resp = $input.first().json;
const status = resp.statusCode || 0;
const model = (() => { try { return $env.OLLAMA_MODEL || 'qwen3-vl-30b'; } catch(e) { return 'qwen3-vl-30b'; } })();
if (status >= 200 && status < 300) {
  logger.info(`[warmup] ${model} warmed OK (HTTP ${status})`);
  return [{ json: { warmed: true, model, status } }];
}
logger.warn(`[warmup] ${model} warmup failed (HTTP ${status}) - first morning chat may see a cold load`);
return [{ json: { warmed: false, model, status } }];
